DO $$ BEGIN IF to_regclass('public.em_workspaces') IS NULL THEN RAISE EXCEPTION 'email execution requires workspace'; END IF; END $$;
CREATE TABLE public.em_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.em_workspaces(id), kind text NOT NULL, dedupe_key text NOT NULL, entity_id uuid, state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','leased','retry','done','dead')), run_after timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0 CHECK(attempts >= 0), lease_token uuid, lease_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,kind,dedupe_key));
CREATE INDEX em_jobs_due_idx ON public.em_jobs(run_after,id) WHERE state IN ('ready','retry','leased');
CREATE TABLE public.em_provider_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.em_workspaces(id), connection_id uuid NOT NULL, provider_event_id text NOT NULL, type text NOT NULL, payload_hash text NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processed','quarantined')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(connection_id,provider_event_id));
ALTER TABLE public.em_jobs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.em_provider_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.em_jobs,public.em_provider_events FROM PUBLIC,anon,authenticated; GRANT ALL ON TABLE public.em_jobs,public.em_provider_events TO service_role;
